        /* Skip hardware-specific operations */
        /* Original: __HAL_UART_CLEAR_IDLEFLAG(huart); */
        /* Original: ATOMIC_SET_BIT(huart->Instance->CR1, USART_CR1_IDLEIE); */

        /* In emulation, we can simulate receiving data immediately */
        /* Use HAL_BE_In to read data from stdin */
        int received = HAL_BE_In(pData, Size);
        if (received > 0)
        {
          huart->RxXferCount = Size - received;
          if (huart->RxXferCount == 0)
          {
            /* Reception complete */
            huart->RxState = HAL_UART_STATE_READY;

            /* IMPORTANT: We do NOT call HAL_UARTEx_RxEventCallback to avoid loops */
            /* Instead, we call the standard receive complete callback */
#if (USE_HAL_UART_REGISTER_CALLBACKS == 1)
            if (huart->RxCpltCallback != NULL)
            {
              huart->RxCpltCallback(huart);
            }
#else
            HAL_UART_RxCpltCallback(huart);
#endif /* USE_HAL_UART_REGISTER_CALLBACKS */
          }
        }
