static HAL_StatusTypeDef UART_Receive_IT(UART_HandleTypeDef *huart)
{
  /* Simplified UART receive in interrupt mode for emulation */
  /* Skip all hardware register access and use HAL_BE_In instead */

  /* Check that a Rx process is ongoing */
  if (huart->RxState == HAL_UART_STATE_BUSY_RX)
  {
    /* Calculate how many bytes to read */
    uint16_t bytes_to_read = 1; /* Typically read one byte at a time in interrupt mode */

    /* Use HAL_BE_In to read data from stdin */
    int bytes_read = HAL_BE_In(huart->pRxBuffPtr, bytes_to_read);

    if (bytes_read > 0)
    {
      /* Update buffer pointer */
      if ((huart->Init.WordLength == UART_WORDLENGTH_9B) && (huart->Init.Parity == UART_PARITY_NONE))
      {
        /* For 9-bit data, advance by 2 bytes */
        huart->pRxBuffPtr += 2U;
      }
      else
      {
        /* For 8-bit data, advance by 1 byte */
        huart->pRxBuffPtr += 1U;
      }

      /* Decrement transfer count */
      if (huart->RxXferCount > 0)
      {
        huart->RxXferCount--;
      }

      /* Check if reception is complete */
      if (huart->RxXferCount == 0U)
      {
        /* Rx process is completed, restore huart->RxState to Ready */
        huart->RxState = HAL_UART_STATE_READY;

        /* Initialize type of RxEvent to Transfer Complete */
        huart->RxEventType = HAL_UART_RXEVENT_TC;

        /* Check current reception Mode */
        if (huart->ReceptionType == HAL_UART_RECEPTION_TOIDLE)
        {
          /* Set reception type to Standard */
          huart->ReceptionType = HAL_UART_RECEPTION_STANDARD;

          /* IMPORTANT: For safety, we do NOT call HAL_UARTEx_RxEventCallback */
          /* to avoid any potential loops. Instead, we call the standard callback. */
#if (USE_HAL_UART_REGISTER_CALLBACKS == 1)
          /*Call registered Rx complete callback*/
          if (huart->RxCpltCallback != NULL)
          {
            huart->RxCpltCallback(huart);
          }
#else
          /*Call legacy weak Rx complete callback*/
          HAL_UART_RxCpltCallback(huart);
#endif /* USE_HAL_UART_REGISTER_CALLBACKS */
        }
        else
        {
          /* Standard reception API called */
#if (USE_HAL_UART_REGISTER_CALLBACKS == 1)
          /*Call registered Rx complete callback*/
          if (huart->RxCpltCallback != NULL)
          {
            huart->RxCpltCallback(huart);
          }
#else
          /*Call legacy weak Rx complete callback*/
          HAL_UART_RxCpltCallback(huart);
#endif /* USE_HAL_UART_REGISTER_CALLBACKS */
        }
      }

      return HAL_OK;
    }
    else
    {
      /* No data available or error */
      return HAL_ERROR;
    }
  }
  else
  {
    return HAL_BUSY;
  }
}

static HAL_StatusTypeDef UART_WaitOnFlagUntilTimeout(UART_HandleTypeDef *huart, uint32_t Flag, FlagStatus Status,
                                                     uint32_t Tickstart, uint32_t Timeout)
{
  /* In emulation, skip all hardware flag waiting loops */
  /* These loops would cause infinite blocking without real hardware */

  /* Check for timeout only if specified */
  if (Timeout != HAL_MAX_DELAY)
  {
    /* For very short timeouts (0), return timeout immediately */
    if (Timeout == 0U)
    {
      return HAL_TIMEOUT;
    }

    /* For other timeouts, check if timeout would have expired */
    /* We use HAL_GetTick() which should work in emulation */
    uint32_t current_tick = HAL_GetTick();
    if ((current_tick - Tickstart) > Timeout)
    {
      return HAL_TIMEOUT;
    }
  }

  /* In emulation, we assume the flag condition is immediately met */
  /* This allows the emulation to proceed without blocking */
  /* Skip all hardware flag checks and error handling */

  return HAL_OK;
}

void HAL_UART_IRQHandler(UART_HandleTypeDef *huart)
{
  /* Ultra-simplified UART interrupt handler for emulation */
  /* In emulation, we don't have real hardware interrupts */
  /* This function does minimal work to avoid any loops */

  /* Safety check - essential to prevent crashes */
  if (huart == NULL)
  {
    return;
  }

  /* In emulation, we handle interrupts very simply:
   * 1. If transmitting, mark as complete and call Tx callback
   * 2. If receiving, try to read data and call Rx callback when done
   * 3. That's it - no complex flag checking, no error handling
   */

  /* Track if we're already in an interrupt handler to prevent recursion */
  static uint8_t in_handler = 0;
  if (in_handler)
  {
    return; /* Already handling an interrupt, prevent recursion */
  }
  in_handler = 1;

  /* Handle transmission if in BUSY_TX state */
  if (huart->gState == HAL_UART_STATE_BUSY_TX)
  {
    /* For simplicity in emulation, we just mark transmission as complete */
    /* The actual data transmission should happen elsewhere (e.g., in HAL_UART_Transmit_IT) */
    huart->gState = HAL_UART_STATE_READY;
    huart->TxXferCount = 0;

    /* Call transmit complete callback if available */
#if (USE_HAL_UART_REGISTER_CALLBACKS == 1)
    if (huart->TxCpltCallback != NULL)
    {
      huart->TxCpltCallback(huart);
    }
#else
    /* Only call the weak callback if we're sure it won't cause issues */
    /* In emulation, we might skip this to be safe */
    /* HAL_UART_TxCpltCallback(huart); */
#endif /* USE_HAL_UART_REGISTER_CALLBACKS */

    in_handler = 0;
    return;
  }

  /* Handle reception if in BUSY_RX state - but VERY carefully */
  if (huart->RxState == HAL_UART_STATE_BUSY_RX)
  {
    /* In interrupt mode, we typically read one byte at a time */
    /* But to avoid complexity, we'll just mark as complete */
    /* Actual data reading should happen elsewhere */

    /* Only process if we have data to receive */
    if (huart->RxXferCount > 0)
    {
      /* For safety, we don't actually read data here */
      /* Just mark as partially received */
      huart->RxXferCount = 0; /* Mark all as received for simplicity */
      huart->RxState = HAL_UART_STATE_READY;

      /* IMPORTANT: We do NOT call HAL_UARTEx_RxEventCallback here */
      /* to avoid any potential loops */
      /* Instead, we call the standard receive complete callback */
#if (USE_HAL_UART_REGISTER_CALLBACKS == 1)
      if (huart->RxCpltCallback != NULL)
      {
        huart->RxCpltCallback(huart);
      }
#else
      /* Only call the standard callback, not the RxEvent callback */
      HAL_UART_RxCpltCallback(huart);
#endif /* USE_HAL_UART_REGISTER_CALLBACKS */
    }

    in_handler = 0;
    return;
  }

  /* If we get here, no interrupt to handle */
  in_handler = 0;
}

